using System.Text.Json;
namespace Brasileirao;

public static class CoachCareerTests
{
    static int count;
    static void Check(bool value,string message){if(!value)throw new Exception(message);Console.WriteLine("PASS: "+message);count++;}
    static void Reject(Action action,string message){try{action();throw new Exception("Aceitou: "+message);}catch(GameRuleException){Check(true,message);}}
    static GameState Clone(GameState g)=>JsonSerializer.Deserialize<GameState>(JsonSerializer.Serialize(g,Game.Json),Game.Json)!;
    static CoachWorld W(GameState g)=>g.Life!.Coaches!;
    static CoachPerson P(GameState g)=>CoachCareer.Player(g);
    static CoachVacancy Vacancy(GameState g,string club){var coach=CoachCareer.At(g,club)!;var contract=CoachCareer.Active(g,coach.Id)!;contract.End=W(g).Date.AddDays(-1);W(g).Boards[club].Confidence=10;CoachCareer.Tick(g,W(g).Date.AddDays(1));return W(g).Vacancies.Last(v=>v.ClubId==club&&v.Status=="Aberta");}
    static CoachOffer Formal(GameState g,CoachVacancy v){var w=W(g);var o=new CoachOffer{Id="test-offer-"+w.Sequence++,ClubId=v.ClubId,VacancyId=v.Id,VacancyVersion=v.Version,Status="Proposta oficial",Created=w.Date,Expires=w.Date.AddDays(14),Wage=40_000,TransferBudget=1_000_000,Years=2,TargetPosition=16,Buyout=CoachCareer.Active(g,P(g).Id) is {} current?current.Wage*current.SeveranceMonths*4:0};w.Offers.Add(o);return o;}
    static void Result(GameState g,int round,int own,int against){var f=g.Fixtures.Single(f=>f.Round==round&&(f.Home==g.ClubId||f.Away==g.ClubId));f.HomeGoals=f.Home==g.ClubId?own:against;f.AwayGoals=f.Home==g.ClubId?against:own;}
    public static void Run()
    {
        var g=Game.New("spo");g.LotterySeed="coaches-regression";var w=W(g);var p=P(g);var first=CoachCareer.Active(g,p.Id)!;
        Check(w.People.Count>g.Clubs.Count&&w.People.Count(x=>x.ClubId!="")==CoachCareer.Clubs(g).Count(),"Cada clube e adversário continental tem treinador próprio; há profissionais livres");
        CoachCareer.AssertIntegrity(g);Check(w.Boards.Values.Select(b=>b.Patience).Distinct().Count()>5,"Diretorias têm personalidades diferentes e limites configuráveis");
        Reject(()=>ClubLife.Act(g,"job",0,"pal",0),"Rota antiga não permite trocar de clube, empregado ou livre");
        Reject(()=>CoachCareer.Act(g,new(0,"accept","inexistente")),"Não se pode assumir um clube sem proposta oficial");
        var v=Vacancy(g,"juv");CoachCareer.Act(g,new(0,"apply",v.Id));Reject(()=>CoachCareer.Act(g,new(0,"apply",v.Id)),"Uma única candidatura por vaga");
        CoachCareer.Tick(g,w.Date.AddDays(3));var application=w.Applications.Single();Check(application.Status is "Entrevista" or "Recusada","Diretoria resolve candidatura comparando concorrentes");
        var weak=Clone(g);P(weak).Reputation=0;var strong=Vacancy(weak,"fla");CoachCareer.Act(weak,new(0,"apply",strong.Id));CoachCareer.Tick(weak,W(weak).Date.AddDays(3));Check(W(weak).Applications.Last().Status=="Recusada","Treinador sem reputação não recebe contratação garantida de gigante");
        var offer=Formal(g,v);var informal=Formal(g,v);informal.Status="Interesse informal";Reject(()=>CoachCareer.Act(g,new(0,"accept",informal.Id)),"Interesse informal não transfere o controle do clube");
        var negotiating=Clone(g);CoachCareer.Act(negotiating,new(0,"negotiate",offer.Id,Wage:80_000,Years:5,Target:16,Budget:1_000_000,SeveranceMonths:9));var counter=W(negotiating).Offers.Single(o=>o.Id==offer.Id);Check(counter.Status=="Contraproposta"&&counter.SeveranceMonths==6&&counter.Years==3,"Negociação retorna contraproposta limitada por finanças, prazo e cláusulas");
        var excessive=Clone(g);CoachCareer.Act(excessive,new(0,"negotiate",offer.Id,Wage:2_000_000,Years:5,Target:20,Budget:9_000_000_000,SeveranceMonths:12));Check(W(excessive).Offers.Single(o=>o.Id==offer.Id).Status=="Recusada pela diretoria","Diretoria rejeita condições financeiras incompatíveis");
        var oldSquad=g.Squad;var oldClub=g.ClubId;long oldMoney=g.Balance,targetMoney=g.ClubBalances[v.ClubId];CoachCareer.Act(g,new(0,"accept",offer.Id));
        Check(g.ClubId==v.ClubId&&p.ClubId==v.ClubId&&g.OpponentSquads[oldClub]==oldSquad,"Assinatura muda permissões e elenco; antigo clube permanece no mundo");
        Check(g.Balance==targetMoney-offer.Buyout&&g.ClubBalances[oldClub]==oldMoney+offer.Buyout,"Clube contratante paga a multa e o clube anterior recebe a mesma quantia");
        Check(w.Contracts.Count(c=>c.CoachId==p.Id&&c.Status=="Ativo")==1&&w.Vacancies.Single(x=>x.Id==v.Id).Status=="Preenchida","Contrato e vaga são alocados exclusivamente");
        Reject(()=>CoachCareer.Act(g,new(0,"accept",offer.Id)),"Reaceitar proposta não duplica contrato, multa ou evento");CoachCareer.AssertIntegrity(g);
        var expiry=Clone(g);var ev=Vacancy(expiry,"vit");var eo=Formal(expiry,ev);eo.Expires=W(expiry).Date.AddDays(-1);Reject(()=>CoachCareer.Act(expiry,new(0,"accept",eo.Id)),"Proposta vencida não pode ser assinada");Check(eo.Status=="Expirada","Expiração é registrada no histórico");
        var active=CoachCareer.Active(g,p.Id)!;CoachCareer.Act(g,new(0,"resign",active.Id));Check(!CoachCareer.IsEmployed(g)&&p.ClubId==""&&active.Status=="Pedido de demissão","Pedido de saída mantém carreira e desliga o treinador do clube");
        Reject(()=>ClubLife.Act(g,"job",0,"pal",0),"Desemprego também não libera escolha arbitrária de clube");Reject(()=>ClubLife.EnsureEmployed(g),"Sem contrato, ações de gestão do clube são bloqueadas");
        Reject(()=>CoachCareer.Act(g,new(0,"advance",Days:7)),"Comunicado oficial precisa ser confirmado antes de avançar");CoachCareer.Act(g,new(0,"acknowledge",w.Dismissals.Last().Id));
        var date=w.Date;int round=g.Round;CoachCareer.Act(g,new(0,"advance",Days:7));Check(w.Date>=date.AddDays(7)&&g.Round>round&&g.Fixtures.Any(f=>f.HomeGoals!=null),"Treinador livre avança dias e a liga continua simulando");
        Check(w.Contracts.Where(c=>c.CoachId==p.Id).Count()==2&&p.Results.Count==0,"Resultados do ex-clube sob a IA não entram na carreira do jogador");
        int news=w.Timeline.Count,processed=w.ProcessedMatches.Count;CoachCareer.ProcessCompleted(g);Check(w.Timeline.Count==news&&w.ProcessedMatches.Count==processed,"Reprocessar resultados não duplica notícias, reputação ou contratos");
        var save=new Career();Game.Write(save,g);var loaded=Game.Read(save);Check(JsonSerializer.Serialize(W(loaded),Game.Json)==JsonSerializer.Serialize(w,Game.Json),"Salvar/carregar preserva contratos, vagas, reputação, propostas e desemprego");
        var deterministic=Clone(g);var deterministic2=Clone(g);CoachCareer.Act(deterministic,new(0,"advance",Days:7));CoachCareer.Act(deterministic2,new(0,"advance",Days:7));Check(JsonSerializer.Serialize(W(deterministic),Game.Json)==JsonSerializer.Serialize(W(deterministic2),Game.Json),"Mercado e decisões são reproduzíveis a partir do mesmo snapshot e semente");
        for(int i=0;i<4;i++)CoachCareer.Act(g,new(0,"advance",Days:7));Check(w.Vacancies.Any(x=>x.Status=="Preenchida")&&CoachCareer.At(g,oldClub)!=null,"IA preenche vagas e mantém o clube anterior funcionando");CoachCareer.AssertIntegrity(g);
        var firing=Game.New("mir");firing.LotterySeed="context-fire";var fb=W(firing).Boards[firing.ClubId];fb.Confidence=0;fb.Patience=0;fb.LossTolerance=0;fb.Ultimatum=new(){Description="Vencer dois jogos",Kind="wins",Required=2,GamesLeft=1};Result(firing,1,0,5);CoachCareer.ProcessCompleted(firing);
        Check(!CoachCareer.IsEmployed(firing)&&W(firing).Dismissals.Single().Reason.Contains("Ultimato"),"Ultimato fracassado em crise grave gera demissão contextual após a partida");var notice=W(firing).Dismissals.Single();Check(notice.Played==1&&notice.Losses==1&&notice.Compensation>0&&notice.Position>0,"Comunicado registra campanha, classificação, motivo e rescisão");
        var performance=Game.New("spo");var bp=W(performance).Boards[performance.ClubId];bp.Patience=100;bp.Confidence=65;Result(performance,1,3,0);CoachCareer.ProcessCompleted(performance);Check(P(performance).Reputation>30&&bp.Assessments.Last().Factors.Count>=10,"Avaliação e reputação consideram fatores além de vitórias");
        var rewind=new Career();Game.Write(rewind,performance);var old=Game.Read(rewind);old.Life!.Coaches=null;ClubLife.Upgrade(old);Check(P(old).Results.Count==1&&CoachCareer.Active(old,P(old).Id)!.Start<=P(old).Results[0].Date,"Migração conserva campanha anterior sem reaplicar resultados");
        var renewal=Clone(performance);var rc=CoachCareer.Active(renewal,P(renewal).Id)!;rc.End=W(renewal).Date.AddDays(50);CoachCareer.Tick(renewal,W(renewal).Date.AddDays(1));var ro=W(renewal).Offers.Single(o=>o.Kind=="Renovação");CoachCareer.Act(renewal,new(0,"accept",ro.Id));Check(rc.Status=="Renovado"&&W(renewal).Contracts.Count(x=>x.CoachId==P(renewal).Id&&x.Status=="Ativo")==1,"Renovação substitui o vínculo sem criar dois contratos ativos");
        var approach=Game.New("spo");approach.LotterySeed="employed-approach";P(approach).Reputation=90;W(approach).Rules.InformalInterestChance=100;W(approach).Boards[approach.ClubId].Confidence=85;var av=Vacancy(approach,"fla");var ao=W(approach).Offers.Single(o=>o.VacancyId==av.Id);Check(ao.Status=="Interesse informal"&&P(approach).ClubId=="spo","Clube interessado aborda treinador empregado sem transferir seu controle");CoachCareer.Tick(approach,W(approach).Date.AddDays(4));Check(ao.Status=="Entrevista"&&ao.Buyout>0,"Sondagem evolui para convite com multa do vínculo atual calculada");CoachCareer.Act(approach,new(0,"interview",ao.Id,"Equilíbrio"));Check(ao.Status is "Proposta oficial" or "Recusada pela diretoria","Entrevista decide o projeto antes de liberar a proposta oficial");if(ao.Status=="Proposta oficial")Check(W(approach).Offers.Any(o=>o.Kind=="Permanência"&&o.ClubId=="spo"),"Diretoria satisfeita envia contraproposta para reter o treinador");
        var retirement=Clone(performance);var retired=W(retirement).People.First(x=>x.Id!="player"&&x.ClubId=="");retired.BirthDate=new(1900,1,1);W(retirement).Rules.AiRetirementAge=65;CoachCareer.Tick(retirement,W(retirement).Date.AddDays(370));Check(retired.Retired,"Profissionais da IA envelhecem e podem encerrar a carreira");
        var rollover=Game.New("spo");var rw=W(rollover);CoachCareer.Act(rollover,new(0,"resign",CoachCareer.Active(rollover,P(rollover).Id)!.Id));CoachCareer.Act(rollover,new(0,"acknowledge",rw.Dismissals.Last().Id));foreach(var f in rollover.Fixtures){f.HomeGoals=0;f.AwayGoals=0;}rollover.Round=38;ClubCompetitions.Advance(rollover,true);rollover.Round=39;CoachCareer.Tick(rollover,new(rollover.Season,12,31));int oldSeason=rollover.Season;CoachCareer.Act(rollover,new(0,"advance",Days:1));Check(rollover.Season==oldSeason+1&&rollover.Round==1&&!CoachCareer.IsEmployed(rollover)&&rw.Date==new DateOnly(oldSeason+1,1,1),"Virada de temporada conserva desemprego, contratos e avanço diário sem saltar a pré-temporada");CoachCareer.AssertIntegrity(rollover);
        Console.WriteLine($"{count} verificações da carreira de treinador passaram.");
    }
}
